const input = $input.first().json;

let rawValue;

if (typeof input === "string") {
  rawValue = input;
} 
else if (Array.isArray(input)) {
  rawValue = input[0];
} 
else if (typeof input.body === "string") {
  rawValue = input.body;
} 
else if (Array.isArray(input.body)) {
  rawValue = input.body[0];
} 
else if (typeof input.data === "string") {
  rawValue = input.data;
} 
else {
  const values = Object.values(input);

  // กรณี n8n แยก string เป็น key 0,1,2,3 เช่น 2 9 . 0 0
  if (values.every(v => typeof v === "string" && v.length === 1)) {
    rawValue = values.join("");
  } else {
    rawValue = values[0];
  }
}

// แปลงค่าเป็นตัวเลข
const soilMoistureRaw = Number(rawValue);

// กำหนดจำนวนทศนิยม
const decimalPlaces = 1;

// ปัดค่าความชื้นดินให้มีทศนิยม 1 ตำแหน่ง
const soilMoisture = Number(soilMoistureRaw.toFixed(decimalPlaces));

return [
  {
    json: {
      site_id: "site01",
      device_id: "esp32_smartfarm_01",

      sensor_type: "soil_moisture",
      sensor_name: "soil_moisture_slave_1",

      modbus_slave_id: 1,
      slave_id: 1,

      virtual_pin: "V2",

      soil_moisture: soilMoisture,
      value: soilMoisture,
      unit: "%",

      soil_moisture_display: soilMoisture.toFixed(decimalPlaces) + " %",

      timestamp: new Date().toISOString(),
      raw_value: rawValue
    }
  }
];
